-- No class/level hand-in gate. Quest faction prerequisites are intentionally bypassed.
-- Recipe quantities/rewards are P99-reviewed; reward magnitudes and limitations are documented in docs/velious-armor-quests.md.
local item_lib = require("items")

function event_say(e)
  if e.message:findi("hail") then
    e.self:Say("Welcome to the Thurgadin Minin' Company, " .. e.other:GetRaceName() .. ". As foreman it's my job to see that me lads are well trained and well cared fer. Unfortunately, we're not in too good shape right now. Ye see, it seems a new vein was struck recently and a bunch of unwelcome critters have come crawlin outta the works attackin' me lads. In order ta help combat this menace I've engineered a new set of armor for the miners, but need some raw materials to get them started.")
  end
  if e.message:findi("new set of armor") then
    e.self:Say("Excellent, " .. e.other:GetCleanName() .. "! I knew ye were the right " .. e.other:GetRaceName() .. " for the job. The pieces I can make are a coif, a tunic, sleeves, bracers, gauntlets, leggings, and boots. This stuff might not be fitting ya if ye're not stealthy like us miners though.")
  end
  if e.message:findi("coif") then
    e.self:Say("To create a piece of armor to protect your sensitive skull. I will require three pieces of crushed coral as well as a corroded chain coif.")
  end
  if e.message:findi("tunic") then
    e.self:Say("To forge a spectacular chain tunic I will require three flawless diamonds and a corroded chain tunic.  With the gems and my skills I may be able to draw out some of its magical powers.")
  end
  if e.message:findi("sleeves") then
    e.self:Say("Protection for your arms will come at the price of three flawed emeralds and a set of corroded chain sleeves.")
  end
  if e.message:findi("bracer") then
    e.self:Say("For the bracers, I will require a corroded chain bracer as well as three crushed flame emeralds.  Return to me when you find such things, " .. e.other:GetCleanName() .. ".")
  end
  if e.message:findi("gauntlets") then
    e.self:Say("Protecting your hands is very important.  I can forge protection for your hands if you bring me a pair of corroded chain gauntlets and three crushed topaz.")
  end
  if e.message:findi("leggings") then
    e.self:Say("A set of corroded chain leggings might be salvageable if you were to find three flawed sea sapphires.  With the right techniques and ingredients almost anything is possible.")
  end
  if e.message:findi("boots") then
    e.self:Say("We use our feet so often, should not they be protected as well as any other portion of our bodies?  If you seek fine protection for your feet, return to me with three pieces of crushed black marble and a set of corroded chain boots.")
  end
end

